code_snippets.parse_list:
def parse_list(self, response):
    for li in response.css('ul li'):
        detail_url = li.css('a::attr(href)').get()
        if detail_url and detail_url.startswith('https://support.terra.bio/hc/en-us/articles/'):
            yield response.follow(detail_url, self.parse_detail)
    next_page = response.css('a.next::attr(href)').get()
    if next_page:
        yield response.follow(next_page, self.parse_list)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('h1.article-title::text').get()
    author = response.css('.author::text').get()
    files = response.css('a[href$=".pdf"]::attr(href)').getall()
    yield {
        'title': title,
        'author': author,
        'files': files
    }
